/* Montra Fleet Maintenance v0.5 - Milestone 2 operational extensions */
IF OBJECT_ID('dbo.SlaClocks','U') IS NULL CREATE TABLE dbo.SlaClocks(Id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,ServiceEventId UNIQUEIDENTIFIER NOT NULL,ClockType NVARCHAR(50) NOT NULL,StartedAt DATETIME2 NOT NULL,DueAt DATETIME2 NULL,PausedAt DATETIME2 NULL,TotalPausedMinutes INT NOT NULL DEFAULT 0,PauseReason NVARCHAR(250) NOT NULL DEFAULT '',Status NVARCHAR(40) NOT NULL DEFAULT 'Running');
IF OBJECT_ID('dbo.WarrantyEntitlements','U') IS NULL CREATE TABLE dbo.WarrantyEntitlements(Id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,VehicleId UNIQUEIDENTIFIER NOT NULL,EntitlementType NVARCHAR(100) NOT NULL,ReferenceNo NVARCHAR(100) NOT NULL,StartDate DATETIME2 NOT NULL,EndDate DATETIME2 NOT NULL,OdometerLimitKm DECIMAL(18,2) NULL,Status NVARCHAR(40) NOT NULL,CoverageNotes NVARCHAR(1000) NOT NULL DEFAULT '');
IF OBJECT_ID('dbo.Campaigns','U') IS NULL CREATE TABLE dbo.Campaigns(Id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,CampaignCode NVARCHAR(50) NOT NULL UNIQUE,Title NVARCHAR(250) NOT NULL,CampaignType NVARCHAR(100) NOT NULL,EffectiveFrom DATETIME2 NOT NULL,EffectiveTo DATETIME2 NULL,ApplicabilityRule NVARCHAR(1000) NOT NULL DEFAULT '',Status NVARCHAR(40) NOT NULL);
IF OBJECT_ID('dbo.VehicleCampaigns','U') IS NULL CREATE TABLE dbo.VehicleCampaigns(Id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,CampaignId UNIQUEIDENTIFIER NOT NULL,VehicleId UNIQUEIDENTIFIER NOT NULL,Status NVARCHAR(40) NOT NULL,ServiceEventId UNIQUEIDENTIFIER NULL,CompletedAt DATETIME2 NULL,CONSTRAINT UQ_VehicleCampaign UNIQUE(VehicleId,CampaignId));
IF OBJECT_ID('dbo.VehicleDocuments','U') IS NULL CREATE TABLE dbo.VehicleDocuments(Id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,VehicleId UNIQUEIDENTIFIER NOT NULL,DocumentType NVARCHAR(100) NOT NULL,FileName NVARCHAR(255) NOT NULL,StorageReference NVARCHAR(1000) NOT NULL,UploadedBy NVARCHAR(100) NOT NULL,UploadedAt DATETIME2 NOT NULL,Status NVARCHAR(40) NOT NULL);
IF OBJECT_ID('dbo.IntegrationOutbox','U') IS NULL CREATE TABLE dbo.IntegrationOutbox(Id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,IntegrationName NVARCHAR(100) NOT NULL,MessageType NVARCHAR(100) NOT NULL,EntityType NVARCHAR(100) NOT NULL,EntityId UNIQUEIDENTIFIER NULL,PayloadJson NVARCHAR(MAX) NOT NULL,Status NVARCHAR(40) NOT NULL,AttemptCount INT NOT NULL DEFAULT 0,CreatedAt DATETIME2 NOT NULL,ProcessedAt DATETIME2 NULL);
GO
